const replaceDocumentContent = `-- name: ReplaceDocumentContent :one
update documents
set kind              = $1,
    tg_file_id        = $2,
    tg_file_unique_id = $3,
    file_size         = $4,
    mime_type         = $5,
    page_count        = nullif($6::integer, 0),
    image_width       = nullif($7::integer, 0),
    image_height      = nullif($8::integer, 0),
    meta_version      = meta_version + 1,
    content_dirty     = ($9::bool and backup_status = 'backed_up'),
    sync_status       = case when $9::bool and backup_status = 'backed_up' then 'pending' else sync_status end,
    sync_reason       = case when $9::bool and backup_status = 'backed_up' then null else sync_reason end,
    updated_at        = now()
where id = $10
  and user_id = $11
  and backup_status not in ('pending', 'uploading')
  and sync_status not in ('pending', 'missing')
returning backup_status
`

type ReplaceDocumentContentParams struct {
	Kind           string
	TgFileID       string
	TgFileUniqueID string
	FileSize       pgtype.Int8
	MimeType       pgtype.Text
	PageCount      int32
	ImageWidth     int32
	ImageHeight    int32
	Cloud          bool
	ID             pgtype.UUID
	UserID         pgtype.UUID
}

// Swaps the file of a document (id, title, category stay). A backed-up document
// is marked content_dirty and sync-pending for the Drive copy when @cloud (Drive
// is connected), otherwise only the row changes. 0 rows: the
// document is gone, uploading, or already has a sync in flight or a missing file.
func (q *Queries) ReplaceDocumentContent(ctx context.Context, arg ReplaceDocumentContentParams) (string, error) {
	row := q.db.QueryRow(ctx, replaceDocumentContent,
		arg.Kind,
		arg.TgFileID,
		arg.TgFileUniqueID,
		arg.FileSize,
		arg.MimeType,
		arg.PageCount,
		arg.ImageWidth,
		arg.ImageHeight,
		arg.Cloud,
		arg.ID,
		arg.UserID,
	)
	var backup_status string
	err := row.Scan(&backup_status)
	return backup_status, err
}

